import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"01 | TDD演示（1）：任务分解法与整体工作流程","description":"","frontmatter":{},"headers":[{"level":2,"title":"TDD 的基本原则","slug":"tdd-的基本原则","link":"#tdd-的基本原则","children":[]},{"level":2,"title":"命令行参数解析","slug":"命令行参数解析","link":"#命令行参数解析","children":[{"level":3,"title":"API 构思与组件划分","slug":"api-构思与组件划分","link":"#api-构思与组件划分","children":[]},{"level":3,"title":"功能分解与任务列表","slug":"功能分解与任务列表","link":"#功能分解与任务列表","children":[]},{"level":3,"title":"红 / 绿循环","slug":"红-绿循环","link":"#红-绿循环","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/01｜TDD演示（1）：任务分解法与整体工作流程.md","filePath":"徐昊·TDD项目实战70讲/01｜TDD演示（1）：任务分解法与整体工作流程.md","lastUpdated":1795563222000}'),p={name:"徐昊·TDD项目实战70讲/01｜TDD演示（1）：任务分解法与整体工作流程.md"};function n(s,e,r,o,E,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_01-tdd演示-1-任务分解法与整体工作流程" tabindex="-1">01 | TDD演示（1）：任务分解法与整体工作流程 <a class="header-anchor" href="#_01-tdd演示-1-任务分解法与整体工作流程" aria-label="Permalink to &quot;01 | TDD演示（1）：任务分解法与整体工作流程&quot;">​</a></h1><p>你好，我是徐昊。今天我们来聊聊测试驱动开发（Test-Driven Development，TDD）。</p><p>测试驱动开发，顾名思义，就是将软件需求转化为一组自动化测试，然后再根据测试描绘的场景，逐步实现软件功能的开发方法。</p><p>在正式开始学习 TDD 之前，我想通过四节课的时间，来演示如何通过 TDD 的方式完成一段</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/1.png" alt=""></a></p><p>完整的功能，让你对 TDD 的做法有个感性的认识。毕竟，我想很多人对 TDD 心存质疑，最主要还是因为不光没吃过猪肉，其实也没见过猪跑吧。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/2.png" alt=""></a></p><h2 id="tdd-的基本原则" tabindex="-1">TDD 的基本原则 <a class="header-anchor" href="#tdd-的基本原则" aria-label="Permalink to &quot;TDD 的基本原则&quot;">​</a></h2><p>为了让我的演示更有针对性，有些基本原则你需要先了解一下。TDD 的创始人 Kent Beck，在他的传世大作 Test-Driven Development by Example 的开篇中给出了 TDD 的基本原则：</p><ol><li><p>当且仅当存在失败的自动化测试时，才开始编写生产代码；</p></li><li><p>消除重复。</p></li></ol><p>不过在今时今日，我认为第二条应该改为“消除坏味道（Bad Smell）”。毕竟重复仅仅是一种坏味道，还有很多不是重复的坏味道。</p><p>那么根据 TDD 的基本原则，Kent Beck 将开发工作分成了三步，也就是后世广为流传的测试驱动开发咒语——红 / 绿 / 重构（Red/Green/Refactoring）：</p><ol><li><p>红：编写一个失败的小测试，甚至可以是无法编译的测试；</p></li><li><p>绿：让这个测试快速通过，甚至不惜犯下任何罪恶；</p></li><li><p>重构：消除上一步中产生的所有重复（坏味道）。</p></li></ol><p>然而红 / 绿 / 重构循环仅仅关注单个测试这个层面，它没有回答测试从何而来。于是很多尝试采用 TDD 的人都卡在了第零步：我该写哪些测试？于是在 2006 年前后我总结了任务分解法，将任务列表作为 TDD 的核心要素。</p><p>任务分解法的步骤如下：</p><ol><li><p>大致构思软件被使用的方式，把握对外接口的方向；</p></li><li><p>大致构思功能的实现方式，划分所需的组件（Component）以及组件间的关系（所谓的架构）。当然，如果没思路，也可以不划分；</p></li><li><p>根据需求的功能描述拆分功能点，功能点要考虑正确路径（Happy Path）和边界条件</p></li></ol><ul><li>（Sad Path）；</li></ul><ol start="4"><li><p>依照组件以及组件间的关系，将功能拆分到对应组件；</p></li><li><p>针对拆分的结果编写测试，进入红 / 绿 / 重构循环。</p></li></ol><p>那么 TDD 的整体工作流程如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/3.png" alt=""></a></p><p>请花几分钟仔细记忆这个流程，它将会在后续所有示例题目中反复出现。</p><h2 id="命令行参数解析" tabindex="-1">命令行参数解析 <a class="header-anchor" href="#命令行参数解析" aria-label="Permalink to &quot;命令行参数解析&quot;">​</a></h2><p>接下来，我会通过 TDD 来实现命令行参数解析的功能。这个练习源自 Robert C. Martin 的<em>Clean Code</em> 第十四章的一个例子。需求描述如下：</p><ul><li><p>我们中的大多数人都不得不时不时地解析一下命令行参数。如果我们没有一个方便的工具，那么我们就简单地处理一下传入 main 函数的字符串数组。有很多开源工具可以完成这个任务，但它们可能并不能完全满足我们的要求。所以我们再写一个吧。</p></li><li><p>传递给程序的参数由标志和值组成。标志应该是一个字符，前面有一个减号。每个标志都应该有零个或多个与之相关的值。例如：</p></li><li><p>-l -p 8080 -d /usr/logs</p></li><li><p>“l”（日志）没有相关的值，它是一个布尔标志，如果存在则为 true，不存在则为false。“p”（端口）有一个整数值，“d”（目录）有一个字符串值。标志后面如果存在多个值，则该标志表示一个列表：</p></li><li><p>-g this is a list -d 1 2 -3 5</p></li><li><p>&quot;g&quot;表示一个字符串列表[“this”, “is”, “a”, “list”]，“d&quot;标志表示一个整数列表[1, 2, -3, 5]。</p></li><li><p>如果参数中没有指定某个标志，那么解析器应该指定一个默认值。例如，false 代表布尔值，0 代表数字，”&quot;代表字符串，[]代表列表。如果给出的参数与模式不匹配，重要的是给出一个好的错误信息，准确地解释什么是错误的。</p></li><li><p>确保你的代码是可扩展的，即如何增加新的数值类型是直接和明显的。</p></li></ul><p>那么接下来，就让我们结合任务分解法使用 TDD 来完成这个需求。</p><h3 id="api-构思与组件划分" tabindex="-1">API 构思与组件划分 <a class="header-anchor" href="#api-构思与组件划分" aria-label="Permalink to &quot;API 构思与组件划分&quot;">​</a></h3><p>首先我们需要考虑，别人将以何种方式使用这段代码，也就是这段代码的整体对外接口部分。我们可以通过写测试的方式，来感受 API 的友好程度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/01/4.png" alt=""></a></p><p>在确定了 API 的形式之后，我们需要大致构思如何实现这个功能：</p><h3 id="功能分解与任务列表" tabindex="-1">功能分解与任务列表 <a class="header-anchor" href="#功能分解与任务列表" aria-label="Permalink to &quot;功能分解与任务列表&quot;">​</a></h3><p>在 API 与实现方式有了方向之后，我们就可以根据需求的描述对功能进行分解了。这里可以先不求全面，有个大致的范围即可：</p><h3 id="红-绿循环" tabindex="-1">红 / 绿循环 <a class="header-anchor" href="#红-绿循环" aria-label="Permalink to &quot;红 / 绿循环&quot;">​</a></h3><p>那么先让我们选择最简单的任务，并通过红绿循环实现它。注意其中绿的环节中，我们是如何“不惜犯下任何罪恶”的！</p><p>之后的两个任务，也要以同样的方式进行：</p><p>到此为止，我们已经完成题目中要求的第一个功能点了：</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>至此为止，我们实现了第一个主要功能：支持由三个不同类型组合而成的命令行参数的解析。</p><p>可以看到，我们在进入 TDD 的红 / 绿 / 重构循环之前做了许多准备工作。我们先花费 2～3 分钟设计了 API，2～3 分钟构思了实现策略，然后在任务分解上花费了更多的时间，差不多有 5分钟。到目前为止，编码的时间大约是 15 分钟。</p><p>这并不像很多原教旨主义 TDD 实践者所推崇的那样，完全依赖重构而不去做设计。然而以我二十年来实践 TDD 的经验来看，理解需求，并通过测试构成高效的节奏，是有效实施 TDD</p><p>的前提。特别是在有其他团队成员的情况下（结对或项目组），更需要如此。希望你能从今天</p><p>起，更加注重“TDD 的准备工作”。</p><p>下节课，我们将在这段代码的基础上开始重构，然后再逐步完成后续的开发。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>如果在思考实现策略的时候，我们选择了其他的实现方式，那么任务分解会有什么不同？</p><p>如果你在学习过程中还有什么问题或想法，欢迎加入读者交流群。最后，也欢迎把你学习这节课的代码与体会分享在留言区，我们下节课再见！</p>',45)])])}const c=t(p,[["render",n]]);export{d as __pageData,c as default};
